{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Story — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#0f1215;--card:#0f171b;--muted:#9aa7a6;--accent:#7ee7d9;--glass:rgba(255,255,255,0.03);--radius:14px}
    html,body{height:100%;margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;color:#e6f7f2;background:linear-gradient(180deg,#071018 0%,#08121a 60%);}
    header{backdrop-filter: blur(6px);position:sticky;top:0;z-index:40;background:linear-gradient(180deg,rgba(7,16,24,0.6),transparent);padding:18px 28px;display:flex;align-items:center;justify-content:space-between}
    .brand{display:flex;gap:12px;align-items:center;color:var(--accent);font-weight:600}
    nav a{color:#dfeffb;text-decoration:none;margin-left:18px;font-size:14px}
    main{max-width:1100px;margin:36px auto;padding:0 20px}
    .hero{display:grid;grid-template-columns:1fr 420px;gap:28px;align-items:center;padding:36px;background:linear-gradient(180deg,rgba(126,231,217,0.03),transparent);border-radius:16px;box-shadow:0 6px 30px rgba(2,6,8,0.6)}
    .hero h1{font-size:32px;margin:0;color:#e8fff9}
    .hero p{color:var(--muted);margin:12px 0 0}
    .hero .cta{margin-top:18px;display:flex;gap:12px}
    .btn{background:var(--accent);border:none;padding:10px 14px;border-radius:10px;color:#012526;font-weight:700;text-decoration:none}
    .ghost{background:transparent;border:1px solid rgba(255,255,255,0.06);color:var(--muted);padding:10px 12px;border-radius:10px}
    .pattern-box{height:240px;border-radius:12px;background:url('assets/img/pattern.svg') center/cover no-repeat;box-shadow:inset 0 0 0 1px rgba(255,255,255,0.02)}

    section{margin-top:28px;opacity:0;transform:translateY(18px);transition:opacity .7s ease,transform .7s ease}
    section.visible{opacity:1;transform:translateY(0)}

    .lead-grid{display:grid;grid-template-columns:1fr 320px;gap:20px}
    .card{background:linear-gradient(180deg,var(--glass),transparent);padding:18px;border-radius:12px}
    .gallery{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
    .tile{height:100px;border-radius:10px;background:linear-gradient(135deg,rgba(126,231,217,0.08),rgba(126,231,217,0.02));display:flex;align-items:center;justify-content:center;color:var(--muted)}

    .faq-list{display:grid;gap:8px}
    .qa{background:rgba(255,255,255,0.02);padding:12px;border-radius:10px}

    footer{margin-top:48px;padding:28px 0;color:var(--muted);text-align:center}

    /* planner */
    .planner{margin-top:18px;padding:14px;border-radius:12px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent)}
    .planner label{display:block;font-size:13px;color:var(--muted);margin:8px 0 4px}
    .planner input,.planner select,.planner textarea{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(255,255,255,0.04);background:transparent;color:#e8fff9}
    .planner .row{display:flex;gap:10px}
    .small{flex:1}
    .planner .actions{display:flex;gap:8px;margin-top:10px}

    @media(max-width:880px){.hero{grid-template-columns:1fr;}.lead-grid{grid-template-columns:1fr}.gallery{grid-template-columns:repeat(2,1fr)}}
  </style>
</head>
<body>
  <header>
    <div class="brand"><svg width="36" height="36" viewBox="0 0 36 36" fill="none" xmlns="http://www.w3.org/2000/svg"><circle cx="18" cy="18" r="17" stroke="url(#g)" stroke-width="2"/></svg><div>{{BUSINESS_NAME}}</div></div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Solo Sessions</a>
      <a href="pricing.html">Investment</a>
      <a href="about.html">Story</a>
      <a href="faq.html">FAQ</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>

  <main>
    <section class="hero" data-reveal>
      <div>
        <h1>A field for deliberate listening</h1>
        <p>We run focused sound gatherings and tailored solo sessions that help you come back to steadiness. Small-group meetups, deep single-session work, and monthly continuity options — each shaped to practical restoration.</p>
        <div class="cta"><a class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a><a class="ghost" href="book.html">Plan a Session</a></div>
      </div>
      <div class="pattern-box" aria-hidden="true"></div>
    </section>

    <section class="lead-grid" data-reveal>
      <div class="card">
        <h3>How we approach sound</h3>
        <p class="muted">We treat tone as a tool for structure — not a show. Sessions are paced, with intentional silences and fixed anchors so the nervous system can notice change without being overwhelmed.</p>
        <ul>
          <li>Measured openings and closings</li>
          <li>Templates you can use at home</li>
          <li>Options for sensory sensitivity</li>
        </ul>

        <div class="planner" id="planner-about">
          <h4 style="margin:0 0 8px 0">Session Planner</h4>
          <label for="pname">Your name</label>
          <input id="pname" placeholder="Optional" />
          <label for="pgoal">Primary intention</label>
          <input id="pgoal" placeholder="Reduce anxiety / Sleep / Clarity / Recovery" />
          <div class="row">
            <div class="small">
              <label for="length">Length (minutes)</label>
              <select id="length"><option>20</option><option selected>40</option><option>60</option><option>90</option></select>
            </div>
            <div class="small">
              <label for="frequency">Weekly frequency</label>
              <select id="frequency"><option>One-off</option><option>Weekly</option><option>Bi-weekly</option><option>Monthly</option></select>
            </div>
          </div>
          <label for="elements">Prefered textures</label>
          <select id="elements" multiple size="3"><option>Crystal tones</option><option>Gongs</option><option>Voice & chant</option><option>Soft percussive</option></select>
          <label for="sensitivity">Sensory notes / Contraindications</label>
          <input id="sensitivity" placeholder="e.g., sound sensitivity, pregnancy, pacemaker" />
          <div class="actions">
            <button class="btn" id="build-about">Build plan</button>
            <button class="ghost" id="download-about">Download</button>
            <button class="ghost" id="copy-about">Copy</button>
          </div>
          <textarea id="summary-about" rows="4" style="margin-top:8px;resize:vertical;display:block;"> </textarea>
        </div>
      </div>

      <aside>
        <div class="card">
          <h4>Quick gallery</h4>
          <div class="gallery" aria-hidden="true">
            <div class="tile">Field</div>
            <div class="tile">Pads</div>
            <div class="tile">Bow</div>
            <div class="tile">Quiet</div>
            <div class="tile">Breathe</div>
            <div class="tile">Anchor</div>
          </div>
        </div>

        <div style="height:12px"></div>

        <div class="card">
          <h4>Book a conversation</h4>
          <p class="muted">Short call to align goals and safety before longer sessions.</p>
          <a class="btn" href="contact.html">Reach out</a>
        </div>
      </aside>
    </section>

    <section data-reveal>
      <h3>What to expect</h3>
      <p class="muted">Sessions open with orientation, move through layered sound phrases, and close with a short integration period. We provide mats and low lighting; you may bring a small blanket or eye cover.</p>
      <ul>
        <li>Arrival & grounding: 7–10 minutes</li>
        <li>Main sound work: curated 20–70 minutes</li>
        <li>Closure & practical takeaways: 5–10 minutes</li>
      </ul>
    </section>

    <section data-reveal>
      <h3>Contraindications & safety notes</h3>
      <p class="muted">Sound practices are gentle but not suitable for everyone. Please tell us if you have a pacemaker, recent concussion, epilepsy, pregnancy beyond the first trimester without prior clearance, or severe hearing conditions. For any medical uncertainty, consult your care provider prior to booking.</p>
    </section>

    <section data-reveal>
      <h3>Still unsure?</h3>
      <p class="muted">If you want a lighter introduction, choose a shorter session or schedule a consult. Our aim is usable calm—tools you can take with you.</p>
      <div style="margin-top:12px"><a class="btn" href="book.html">Start a reservation</a></div>
    </section>

    <footer>
      <small>Call {{PHONE}} • {{EMAIL}} • {{CITY}}, {{STATE}}</small>
    </footer>
  </main>

  <script>
    // Scroll reveal with reduced-motion respect
    (function(){
      var prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      var els = document.querySelectorAll('[data-reveal]');
      if(prefersReduced){ els.forEach(function(s){ s.classList.add('visible'); }); return; }
      var io = new IntersectionObserver(function(entries){ entries.forEach(function(e){ if(e.isIntersecting){ e.target.classList.add('visible'); io.unobserve(e.target); } }); },{threshold:0.12});
      els.forEach(function(s){ io.observe(s); });
    })();
  </script>

  <script>
    // Session Planner (about)
    (function(){
      function q(id){return document.getElementById(id)}
      var build = q('build-about'), copy = q('copy-about'), dl = q('download-about');
      function collect(){
        var name = q('pname').value.trim();
        var goal = q('pgoal').value.trim();
        var length = q('length').value;
        var frequency = q('frequency').value;
        var elements = Array.from(q('elements').selectedOptions).map(function(o){return o.value;}).join(', ') || 'Open';
        var notes = q('sensitivity').value.trim() || 'None noted';
        var lines = [];
        if(name) lines.push('Name: '+name);
        lines.push('Intention: '+(goal||'General balance'));
        lines.push('Duration: '+length+' minutes');
        lines.push('Cadence: '+frequency);
        lines.push('Textures: '+elements);
        lines.push('Safety notes: '+notes);
        lines.push('\nSuggested frame:');
        lines.push('- Arrival / orientation: 8–10 min');
        lines.push('- Main work: approx '+length+' min, structured in phased anchors');
        lines.push('- Closure & takeaways: 6–8 min');
        return lines.join('\n');
      }
      build.addEventListener('click',function(){ q('summary-about').value = collect(); });
      copy.addEventListener('click',function(){ var t=collect(); if(navigator.clipboard){navigator.clipboard.writeText(t);} else { var ta=document.createElement('textarea'); ta.value=t; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); ta.remove(); } alert('Plan copied to clipboard'); });
      dl.addEventListener('click',function(){ var blob=new Blob([collect()],{type:'text/plain'}); var url=URL.createObjectURL(blob); var a=document.createElement('a'); a.href=url; a.download='session-plan.txt'; document.body.appendChild(a); a.click(); a.remove(); URL.revokeObjectURL(url); });
    })();
  </script>

</body>
</html>"} 
{"path":"faq.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Questions — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071018;--card:#071a1b;--muted:#9db3b1;--accent:#a8fff0}
    body{margin:0;background:radial-gradient(1200px 400px at 10% 10%, rgba(126,231,217,0.05), transparent),var(--bg);color:#eafbf7;font-family:Inter,system-ui;}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 24px;position:sticky;top:0;background:linear-gradient(180deg,rgba(7,16,24,0.6),transparent);backdrop-filter:blur(6px)}
    nav a{color:#dff; margin-left:14px;text-decoration:none;font-size:14px}
    main{max-width:980px;margin:36px auto;padding:0 18px}
    .hero{padding:28px 18px;border-radius:14px;background:linear-gradient(180deg,rgba(168,255,240,0.02),transparent);display:flex;gap:18px;align-items:center}
    .hero h1{margin:0;font-size:28px}
    .muted{color:var(--muted)}
    .cta{margin-left:auto}
    .btn{background:var(--accent);border:none;padding:10px 14px;border-radius:10px;color:#043; font-weight:700}

    .content{display:grid;grid-template-columns:1fr 340px;gap:20px;margin-top:20px}
    .faq{background:rgba(255,255,255,0.02);padding:18px;border-radius:12px}
    .qa{padding:12px;border-radius:8px;background:linear-gradient(180deg,transparent,rgba(255,255,255,0.01));margin-bottom:8px}
    .qa h4{margin:0}
    .aside{position:relative}
    .card{padding:14px;border-radius:12px;background:rgba(255,255,255,0.02)}

    section{opacity:0;transform:translateY(12px);transition:opacity .6s ease,transform .6s ease}
    section.visible{opacity:1;transform:none}

    .small{font-size:13px;color:var(--muted)}
    footer{margin-top:40px;text-align:center;color:var(--muted)}

    @media(max-width:920px){.content{grid-template-columns:1fr}.cta{margin-left:0}}
  </style>
</head>
<body>
  <header>
    <div style="color:var(--accent);font-weight:700">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Solo</a>
      <a href="pricing.html">Rates</a>
      <a href="about.html">Story</a>
      <a href="faq.html">Questions</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <section class="hero" data-reveal>
      <div>
        <h1>Questions and considerations</h1>
        <p class="muted">Practical notes about attending, accessibility, and safety for sound gatherings and private sessions.</p>
      </div>
      <div class="cta"><a class="btn" href="book.html">Make a reservation</a></div>
    </section>

    <div class="content">
      <section class="faq" data-reveal>
        <h3>Frequently asked</h3>
        <div class="qa">
          <h4>What should I bring?</h4>
          <p class="small">Comfortable clothing, a small blanket or light pillow, and any personal hearing aids if you use them. We provide mats, bolsters, and headphones when needed.</p>
        </div>

        <div class="qa">
          <h4>Will the sound be loud?</h4>
          <p class="small">No. Sessions are intentionally calibrated. We introduce anchors at gentle levels, and there are options for milder textures if you're sensitive.</p>
        </div>

        <div class="qa">
          <h4>Is this therapy?</h4>
          <p class="small">These are experiential sessions aimed at regulation and restoration, not a replacement for psychotherapy or medical care.</p>
        </div>

        <div class="qa">
          <h4>Can I leave early?</h4>
          <p class="small">Yes. You may step out quietly at any time. Let the facilitator know if you are concerned about sensory overload.</p>
        </div>

        <div class="qa">
          <h4>Booking, cancellations, and refunds</h4>
          <p class="small">Full policy is available on the booking page. We offer a small-window refund with notice; later cancellations may receive a credit toward future classes.</p>
        </div>

      </section>

      <aside class="aside">
        <div class="card" data-reveal>
          <h4>Safety & contraindications</h4>
          <p class="small">If you have a pacemaker, recent head trauma, epilepsy, or uncertain pregnancy status, please check with your clinician before attending and tell us before booking. We can adapt many sessions but will not proceed when there is a clear medical risk.</p>
        </div>

        <div style="height:12px"></div>

        <div class="card" data-reveal>
          <h4>Need a lighter start?</h4>
          <p class="small">Choose an introductory 20-minute format or arrange a brief consult to preview the approach.</p>
          <a class="btn" href="book.html">Intro Session</a>
        </div>

      </aside>
    </div>

    <section data-reveal style="margin-top:20px">
      <h3>Uncommon questions</h3>
      <div class="qa"><h4>Can children attend?</h4><p class="small">Sessions are designed for adults and youth with consent and a guardian present. Contact us so we can assess suitability.</p></div>
      <div class="qa"><h4>Are pets allowed?</h4><p class="small">Not during public sessions. Service animals are evaluated case-by-case.</p></div>
    </section>

    <footer>
      <small>Questions? Call {{PHONE}} or email {{EMAIL}} • {{CITY}}, {{STATE}}</small>
    </footer>
  </main>

  <script>
    // Scroll reveal with prefer-reduced-motion
    (function(){
      var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      var nodes = document.querySelectorAll('[data-reveal]');
      if(reduced){ nodes.forEach(function(n){n.classList.add('visible');}); return; }
      var obs = new IntersectionObserver(function(entries){ entries.forEach(function(e){ if(e.isIntersecting) { e.target.classList.add('visible'); obs.unobserve(e.target); } }); },{threshold:0.08});
      nodes.forEach(function(n){ obs.observe(n); });
    })();
  </script>

</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Reserve — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#02121a;--card:#082126;--muted:#9dc3bd;--accent:#65f3e3}
    body{margin:0;background:linear-gradient(180deg,#031019 0%,#071622 100%);font-family:Inter,system-ui;color:#eafefb}
    header{display:flex;align-items:center;justify-content:space-between;padding:14px 20px;background:linear-gradient(180deg,rgba(3,6,8,0.6),transparent);position:sticky;top:0}
    nav a{color:#ddf; margin-left:12px;text-decoration:none}
    main{max-width:980px;margin:28px auto;padding:0 18px}
    .lead{display:flex;gap:18px;align-items:center;padding:18px;background:linear-gradient(180deg,rgba(101,243,227,0.02),transparent);border-radius:12px}
    .lead h1{margin:0;font-size:26px}
    .packages{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:16px}
    .pack{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:12px;border-radius:12px}
    .price{font-weight:700;color:var(--accent);font-size:20px}
    .muted{color:var(--muted)}

    .planner{margin-top:18px;padding:12px;border-radius:10px;background:rgba(255,255,255,0.02)}
    label{font-size:13px;color:var(--muted)}
    input,select,textarea{width:100%;padding:8px;border-radius:8px;border:1px solid rgba(255,255,255,0.04);background:transparent;color:#eafefb;margin-top:6px}
    .row{display:flex;gap:8px}
    .btn{background:var(--accent);border:none;padding:10px 12px;border-radius:10px;font-weight:700;color:#023}
    .ghost{background:transparent;border:1px solid rgba(255,255,255,0.04);color:var(--muted);padding:10px 12px;border-radius:10px}

    section{opacity:0;transform:translateY(12px);transition:opacity .6s ease,transform .6s ease}
    section.visible{opacity:1;transform:none}

    .disclaimer{background:rgba(255,255,255,0.02);padding:12px;border-radius:10px;margin-top:12px;color:var(--muted)}

    @media(max-width:920px){.packages{grid-template-columns:1fr}.lead{flex-direction:column}}
  </style>
</head>
<body>
  <header>
    <div style="font-weight:700;color:var(--accent)">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Private</a>
      <a href="pricing.html">Rates</a>
      <a href="about.html">Story</a>
      <a href="faq.html">Help</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <section class="lead" data-reveal>
      <div>
        <h1>Reserve a session</h1>
        <p class="muted">Choose a format and lock in time. If you'd like a short strategy call first, select "Consult" below.</p>
      </div>
      <div style="margin-left:auto"><a class="btn" href="contact.html">Request a consult</a></div>
    </section>

    <section data-reveal>
      <h3>Our session menus</h3>
      <div class="packages">
        <div class="pack">
          <div class="price">Intro 20m</div>
          <p class="muted">A focused introduction — a practical way to try the format.</p>
          <div style="margin-top:8px"><a class="btn" href="#book-form">Select</a></div>
        </div>
        <div class="pack">
          <div class="price">Core 40m</div>
          <p class="muted">Balanced opening, main phase, and short integration. Most chosen.</p>
          <div style="margin-top:8px"><a class="btn" href="#book-form">Select</a></div>
        </div>
        <div class="pack">
          <div class="price">Deep 70m</div>
          <p class="muted">Extended work for deeper recalibration and time for integration.</p>
          <div style="margin-top:8px"><a class="btn" href="#book-form">Select</a></div>
        </div>
      </div>
    </section>

    <section id="book-form" data-reveal>
      <h3>Reservation form</h3>
      <div class="planner" id="planner-book">
        <label for="bname">Name</label>
        <input id="bname" placeholder="Full name" />
        <label for="bemail">Email</label>
        <input id="bemail" placeholder="you@example.com" />
        <div class="row" style="margin-top:8px">
          <div style="flex:1">
            <label for="bpackage">Package</label>
            <select id="bpackage"><option>Intro 20m</option><option selected>Core 40m</option><option>Deep 70m</option></select>
          </div>
          <div style="flex:1">
            <label for="bdate">Preferred date</label>
            <input id="bdate" placeholder="YYYY-MM-DD" />
          </div>
        </div>
        <label for="bnotes">Notes (sensory notes, contraindications)</label>
        <textarea id="bnotes" rows="3" placeholder="e.g., sensitive to high volumes, recent surgery, pacemaker"></textarea>
        <div style="display:flex;gap:8px;margin-top:10px">
          <button class="btn" id="preview-book">Preview booking</button>
          <button class="ghost" id="submit-book">Submit request</button>
          <button class="ghost" id="copy-book">Copy summary</button>
        </div>
        <textarea id="summary-book" rows="5" style="margin-top:10px;display:block"></textarea>
      </div>

      <div class="disclaimer">
        <strong>Safety note:</strong> Please disclose pacemakers, recent concussions, epilepsy, or pregnancy. For medical concerns, consult your health provider before attending. We may decline or adapt sessions if medical risk is present.
      </div>
    </section>

    <section data-reveal>
      <h3>What happens after you submit</h3>
      <p class="muted">We’ll follow up by email to confirm availability and any required intake questions. For continuity bookings, we offer discounted monthly credits — ask us during confirmation.</p>
    </section>

    <footer style="margin-top:28px;color:var(--muted)"><small>Questions? Call {{PHONE}} or email {{EMAIL}} — {{CITY}}, {{STATE}}</small></footer>
  </main>

  <script>
    // scroll reveal
    (function(){
      var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      var elements = document.querySelectorAll('[data-reveal]');
      if(reduced){ elements.forEach(function(e){ e.classList.add('visible'); }); return; }
      var observer = new IntersectionObserver(function(entries){ entries.forEach(function(en){ if(en.isIntersecting){ en.target.classList.add('visible'); observer.unobserve(en.target); } }); },{threshold:0.1});
      elements.forEach(function(el){ observer.observe(el); });
    })();

    // Booking planner interactions
    (function(){
      function el(id){return document.getElementById(id)}
      var preview = el('preview-book'), submit = el('submit-book'), copy = el('copy-book');
      function summary(){
        var name = el('bname').value.trim()||'—';
        var email = el('bemail').value.trim()||'—';
        var pack = el('bpackage').value;
        var date = el('bdate').value.trim()||'Flexible';
        var notes = el('bnotes').value.trim()||'No notes';
        var out = [];
        out.push('Reservation request');
        out.push('Name: '+name);
        out.push('Email: '+email);
        out.push('Package: '+pack);
        out.push('Requested date: '+date);
        out.push('Notes: '+notes);
        out.push('\nNext steps: We will reply with availability and a short intake. If there are safety notes, we may request a brief consult first.');
        return out.join('\n');
      }
      preview.addEventListener('click',function(){ el('summary-book').value = summary(); });
      copy.addEventListener('click',function(){ var t=summary(); if(navigator.clipboard){ navigator.clipboard.writeText(t); } else { var ta=document.createElement('textarea'); ta.value=t; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); ta.remove(); } alert('Reservation summary copied'); });
      submit.addEventListener('click',function(){ alert('Request submitted. We will contact you at the provided email.'); });
    })();
  </script>
